    public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_CORNER_BASE = "\n    float RBox(float2 p,float2 b,float r){\n        float2 q=abs(p)-b+r;\n        return min(max(q.x,q.y),0.)+length(max(q,0.))-r;\n    }";
    public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_CORNER_BEZIER = "\n    float cubicBezierDistance(vec2 p, vec2 p0, vec2 p1, vec2 p2, vec2 p3) {\n        // 将贝塞尔转换为幂基形式：B(t) = c0 + c1 t + c2 t^2 + c3 t^3\n        vec2 c0 = p0;\n        vec2 c1 = 3.0 * (p1 - p0);\n        vec2 c2 = 3.0 * (p2 - 2.0 * p1 + p0);\n        vec2 c3 = p3 - 3.0 * p2 + 3.0 * p1 - p0;\n    \n        float t = 0.5; // 初始值\n        for (int i = 0; i < 10; i++) {\n            vec2 Bt   = ((c3 * t + c2) * t + c1) * t + c0;\n            vec2 dBt  = (3.0 * c3 * t + 2.0 * c2) * t + c1;\n            vec2 ddBt = 6.0 * c3 * t + 2.0 * c2;\n            vec2 r    = Bt - p;\n            // E(t) = |B(t)-p|^2 的一阶、二阶导\n            float f1 = dot(dBt, r);\n            float f2 = dot(ddBt, r) + dot(dBt, dBt);\n            // 避免除零\n            float denom = max(f2, 1e-4);\n            t = clamp(t - f1 / denom, 0.0, 1.0);\n        }\n        vec2 Bt = ((c3 * t + c2) * t + c1) * t + c0;\n        vec2 re = Bt - p;\n    \n        // 计算曲线在最近点处的切线向量\n        vec2 tangent = (3.0 * c3 * t + 2.0 * c2) * t + c1;\n        \n        // 计算法向量（切线逆时针旋转90度）\n        vec2 normal = vec2(-tangent.y, tangent.x);\n        \n        // 归一化法向量\n        vec2 normalizedNormal = normalize(normal);\n        \n        // 计算有符号距离\n        float dis = length(re);\n        float signedDistance = dot(re, normalizedNormal) > 0.0 ? dis : -dis;\n    \n        return signedDistance ;\n    }\n    float sdBezierDistance(vec2 p, vec2 b, float cc) {\n        float sdf = 0.0;\n        if(any(lessThanEqual(abs(p), b - cc))) {\n            sdf = RBox(p, b, cc);\n        }else{\n            float point  = max(cc*u_weight*0.5,0.001);\n            sdf = cubicBezierDistance(abs(p)-b+cc,vec2(cc, 0.0), vec2(cc, point), vec2(point, cc),vec2(0.0, cc));\n        }\n        return sdf;\n    }\n";
    public static final String GRADIENT_STROKE_SHADER_STRING_METHOD_CORNER_SMOOTH = "\n    float approx_sdSquircle(vec2 p, float n){\n        // symmetries\n        p = abs(p); // if( p.y>p.x ) p=p.yx;\n        float w = pow(p.x,n) + pow(p.y,n);\n\n        // linearlized implicit (taylor)\n        float b = 2.0*n-2.0;\n        float a = 1.0-1.0/n;\n        return (w-pow(w,a)) * inversesqrt(pow(p.x,b)+pow(p.y,b));\n    }\n\n    float opSmoothIntersectionOne(float d1,float d2){\n        float h=clamp(.5-.5*(d2-d1),0.,1.);\n        return mix(d2,d1,h) + h*(1.-h);\n    }\n    vec2 getPreCalcMA() {\n        float halfSizeX = u_size.x * 0.5;\n        float halfSizeY = u_size.y * 0.5;\n        float maX = 0.0;\n        float maY = 0.0;\n        if (halfSizeX > halfSizeY) {\n            maX = halfSizeX;\n            maY = halfSizeY * 0.5;\n        } else {\n            maX = halfSizeX * 0.5;\n            maY = halfSizeY;\n        }\n        return vec2(maX, maY);\n    }\n\n    vec2 sdRoundedBoxMerge(vec2 p,  vec2 b,  float cr){\n        vec2 q1 = abs(p)-b;\n        float r1 = min(max(q1.x,q1.y),0.0) + length(max(q1,0.0));\n        vec2 q2 = q1 + cr;\n        float r2 = min(max(q2.x,q2.y),0.0) + length(max(q2,0.0)) - cr;\n        float h=clamp(.5-.5*(r2-r1),0.,1.);\n        return vec2(mix(r2,r1,h)+h*(1.-h), r2);\n    }\n\n    float sdSquircle(vec2 p, in vec2 b, float cc) {\n        float sdf = 0.0;\n        float sc =  cc + u_weight * cc;\n        float rbRes = 0.0;\n        if(any(lessThan(abs(p), b - sc))) {\n            vec2 res = sdRoundedBoxMerge(p, b, cc);\n            sdf = res.x;\n            rbRes = res.y;\n        } else {\n            vec2 sp = (abs(p) - b + sc) / sc;\n            float angle = abs(atan(sp.y, sp.x) - 0.785398); // 0.785398 for 45 degree\n            float preCalcN1Delta = 3.02 + u_weight * 2.44;\n            float preCalcN2Delta = 2.05 + u_weight * 2.44;\n            float sn = mix(preCalcN1Delta, preCalcN2Delta, smoothstep(22.0, 0.0, degrees(angle)));\n            sdf = approx_sdSquircle(sp, sn) * sc;\n            rbRes = RBox(p, b, cc);\n            sdf = opSmoothIntersectionOne(sdf, rbRes);\n        }\n\n        if((u_corner) == min(b.x, b.y)) {\n            float sdfRect = RBox(p, getPreCalcMA(), 0);\n            sdf = min(max(sdfRect, rbRes), sdf);\n        }\n\n        // return smoothstep(0.0, -antiAliasing, sdf);\n        return sdf;\n    }";
